// Morph between saw, tri & sine as seen in Lumen.

#define uv (gl_FragCoord.xy/iResolution.xy)
#define PI 3.1415
#define time iTime
#define speed .25

float fold (float f) {
   float th1 = clamp(f, 0.0, 0.5);
   float th2 = clamp(f, 0.5, 1.0);

   return (((1.0-th1)+th2)-1.)*2.;
}

float freq = 2.5;
float symmetry = 0.; // -> Saw = 0. / Trig = .5 / Sin = 1.

void mainImage(out vec4 fragColor, in vec2 fragCoord) {

     //--Palindrome Animation--
     symmetry = abs(mod(time*speed, 1.0)*2.-1.); // -> Comment or Erase.

    float sym1 = clamp(symmetry, 0., 0.5);
    float sym2 = clamp(symmetry, 0.5, 1.)*2.-1.;

    float sawtooth = fract(uv.x * freq);

    float saw2trig = (sawtooth < sym1) 
                 ? pow((sawtooth / sym1), 0.5)
                 : pow((1.0 - sawtooth) / (1.0 - sym1), 0.5);

    float sine = 1.-fold(sin(sawtooth*PI)*0.5);

    float wave = mix(saw2trig, sine, sym2);                 

    fragColor = vec4(vec3(wave), 1.0);

    //---1D Waveform Overlay---
    float scope = step(fract(-uv.y+wave*0.5-0.75), 0.025);
    vec4 waveScopeMix = wave-vec4(vec3(scope),1.0);
         waveScopeMix = clamp(waveScopeMix, 0.0, 1.0);
         waveScopeMix = waveScopeMix+vec4(0,scope,0,1);

    fragColor = waveScopeMix;
    //------------------------
}
